<template>
  <div class="intelligence-page">
    <header class="hero"><div><p>DECISION SIGNALS · READ ONLY</p><h2>智能分析中心</h2><span>先确认数据可信度，再基于趋势、活跃告警与安全基线安排人工排查。</span></div><div class="hero-actions"><el-segmented v-model="windowHours" :options="windowOptions" @change="load(false)" /><el-button :icon="Refresh" :loading="loading" @click="load(true)">刷新分析</el-button></div></header>
    <div class="summary-grid"><div v-for="card in cards" :key="card.label" class="summary-card" :class="card.tone"><span>{{ card.label }}</span><strong>{{ card.value }}</strong><small>{{ card.desc }}</small></div></div>
    <div class="readiness-grid"><AnalysisCoverageCard :coverage="globalCoverage" /><section class="context-card"><p>WINDOW CONTEXT</p><h3>{{ windowLabel }} 分析窗口</h3><div class="context-stats"><span><b>{{ summary?.readyNodeCount || 0 }}</b> 结论可用</span><span><b>{{ summary?.insufficientNodeCount || 0 }}</b> 样本不足</span></div><small>24 小时窗口适合快速观察；7 天用于日常判断；30 天用于容量趋势。所有结论均为只读辅助信息。</small></section></div>
    <section class="panel"><div class="panel-head"><div><h3>风险优先级队列</h3><p>风险类型说明了结论来源；样本不足资源单独标示，不会被当作稳定或低风险。</p></div><div class="filters"><el-select v-model="severityFilter" clearable placeholder="全部等级" style="width:118px"><el-option label="紧急" value="critical" /><el-option label="关注" value="warning" /><el-option label="稳定" value="info" /></el-select><el-select v-model="typeFilter" clearable placeholder="全部类型" style="width:132px"><el-option v-for="item in riskTypeOptions" :key="item.value" :label="item.label" :value="item.value" /></el-select></div></div>
      <el-table v-loading="loading" :data="filteredHosts" row-key="node" class="risk-table" @row-click="openHost"><el-table-column label="资源 / 数据状态" min-width="200"><template #default="{row}"><strong>{{ row.node }}<em v-if="row.ip" class="host-ip">{{ row.ip }}</em></strong><small>{{ row.group || '未分组' }} · {{ row.coverage?.ready ? '数据已就绪' : '样本不足' }}</small></template></el-table-column><el-table-column label="优先级" width="102"><template #default="{row}"><el-tag :type="tagType(row.severity)" effect="dark">{{ severityText(row.severity) }}</el-tag></template></el-table-column><el-table-column label="类型" min-width="150"><template #default="{row}"><span v-if="row.riskTypes?.length" class="type-tags"><i v-for="type in row.riskTypes" :key="type">{{ typeText(type) }}</i></span><span v-else class="muted">暂无风险信号</span></template></el-table-column><el-table-column label="关键结论" min-width="300"><template #default="{row}"><span v-if="row.evidence?.length">{{ row.evidence[0].title }}</span><span v-else-if="!row.coverage?.ready" class="muted">{{ row.coverage?.message }}</span><span v-else class="muted">历史数据处于稳定范围</span></template></el-table-column><el-table-column label="评分" width="74"><template #default="{row}"><b :class="['score',row.severity]">{{ row.score }}</b></template></el-table-column></el-table>
      <el-empty v-if="!loading&&!filteredHosts.length" description="当前筛选条件下没有分析结果" />
    </section>
    <el-drawer v-model="drawer" :title="drawerTitle" size="min(760px,94vw)"><template v-if="selected"><div class="drawer-score"><div><span>综合风险评分</span><strong :class="selected.severity">{{ selected.score }}</strong></div><div><el-tag :type="tagType(selected.severity)" effect="dark">{{ severityText(selected.severity) }}</el-tag><p>{{ selected.coverage?.ready ? '数据结论可用' : '数据仍在采集，结论有限' }}</p></div></div><AnalysisCoverageCard :coverage="selected.coverage" />
      <section class="drawer-section"><h4>关联证据</h4><div v-for="item in selected.evidence" :key="item.title" class="evidence"><el-tag size="small" :type="tagType(item.severity)">{{ typeText(item.type) }}</el-tag><div><b>{{ item.title }}</b><p>{{ item.detail }}</p><small>{{ item.suggestion }}</small></div></div><el-empty v-if="!selected.evidence?.length" description="未发现持续偏离、活跃告警或紧迫容量风险" :image-size="52" /></section>
      <section class="drawer-section"><h4>可能根因与影响范围</h4><p class="correlation-note">基于资源归属和同主机信号的关联线索，不代表已确认因果关系。</p><article v-for="item in selected.correlations" :key="item.kind" class="correlation"><div class="correlation-head"><b>{{ item.title }}</b><el-tag size="small" :type="confidenceType(item.confidence)">{{ confidenceText(item.confidence) }}</el-tag></div><p>{{ item.summary }}</p><div v-if="item.impact?.length" class="impact-list"><span v-for="impact in item.impact" :key="impact.kind+impact.name"><b>{{ impact.kind }}</b> · {{ impact.name }} <i>{{ impact.status }}</i></span></div><small>{{ item.recommendation }}</small></article><el-empty v-if="!selected.correlations?.length" description="未形成明确归属的关联链路" :image-size="52" /></section>
      <section class="drawer-section"><h4>动态基线趋势</h4><BaselineTrendChart v-for="item in selected.baselines" :key="item.metric+JSON.stringify(item.labels)" :baseline="item" :window-label="windowLabel" /></section>
      <section class="drawer-section"><h4>容量预测</h4><div v-for="item in selected.forecasts" :key="JSON.stringify(item.labels)" class="forecast"><b>{{ item.labels?.mount || item.labels?.device || '磁盘分区' }}</b><span v-if="item.status==='unknown'">{{ item.reason }}</span><span v-else>{{ forecastText(item) }} · 当前 {{ one(item.latest) }}% · 拟合度 {{ one(item.rSquared) }}</span></div></section></template></el-drawer>
  </div>
</template>
<script setup>
import { computed,onMounted,ref } from 'vue'
import { Refresh } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import http from '../../api/http'
import AnalysisCoverageCard from './AnalysisCoverageCard.vue'
import BaselineTrendChart from './BaselineTrendChart.vue'
const summary=ref(null),loading=ref(false),windowHours=ref(168),severityFilter=ref(''),typeFilter=ref(''),drawer=ref(false),selected=ref(null)
const windowOptions=[{label:'24 小时',value:24},{label:'7 天',value:168},{label:'30 天',value:720}];const riskTypeOptions=[{value:'anomaly',label:'持续异常'},{value:'capacity',label:'容量风险'},{value:'availability',label:'主机离线'},{value:'alert',label:'活跃告警'},{value:'security',label:'安全风险'}]
const windowLabel=computed(()=>({24:'24 小时',168:'7 天',720:'30 天'})[windowHours.value]);const cards=computed(()=>{const s=summary.value;const none=s?0:'-';return[{label:'需关注资源',value:s?(s.riskCount||0):none,desc:'有明确风险证据',tone:'orange'},{label:'持续异常',value:s?(s.anomalyCount||0):none,desc:'连续偏离动态基线',tone:'yellow'},{label:'容量紧迫',value:s?(s.urgentCapacityCount||0):none,desc:'预计 7 天内耗尽',tone:'red'},{label:'数据已就绪',value:s?(s.readyNodeCount||0):none,desc:`共 ${s?.nodeCount||0} 个节点`,tone:'cyan'}]})
const globalCoverage=computed(()=>{const total=summary.value?.nodeCount||0,ready=summary.value?.readyNodeCount||0;return{ready:total>0&&ready===total,requiredSamples:24,validSamples:total?Math.round(ready/total*24):0,message:total?`${ready} / ${total} 个节点已具备完整关键指标基线`:'等待主机历史指标进入分析窗口',missingMetrics:[]}})
const filteredHosts=computed(()=> (summary.value?.hosts||[]).filter(h=>(!severityFilter.value||h.severity===severityFilter.value)&&(!typeFilter.value||h.riskTypes?.includes(typeFilter.value))))
const drawerTitle=computed(()=>{const s=selected.value;return s?(s.ip?`${s.node} · ${s.ip}`:s.node):'分析详情'})
function tagType(value){return({critical:'danger',warning:'warning',info:'success'})[value]||'info'}function severityText(value){return({critical:'紧急',warning:'关注',info:'稳定'})[value]||'未知'}function typeText(value){return({anomaly:'持续异常',capacity:'容量风险',availability:'主机离线',alert:'活跃告警',security:'安全风险',security_event:'安全事件'})[value]||value}function confidenceType(value){return value==='high'?'danger':value==='medium'?'warning':'info'}function confidenceText(value){return({high:'高置信线索',medium:'中置信线索',low:'低置信线索'})[value]||'关联线索'}function one(v){return Number(v||0).toFixed(1)}function forecastText(item){return item.daysRemaining<1?'不足 1 天耗尽':`约 ${Math.ceil(item.daysRemaining)} 天后耗尽`}
function openHost(row){selected.value=row;drawer.value=true}async function load(refresh=false){loading.value=true;try{summary.value=await http.analysisSummary(windowHours.value,refresh)}catch(error){console.error('加载智能分析失败',error);ElMessage.error('智能分析加载失败：'+(error.message||'请稍后重试'))}finally{loading.value=false}}onMounted(load)
</script>
<style scoped>
