lex-wrap:wrap;gap:4px}.type-tags i{padding:2px 6px;border-radius:5px;color:#a5b4fc;background:rgba(99,102,241,.16);font-size:11px;font-style:normal}.score{font-size:18px}.score.critical{color:#f87171}.score.warning{color:#fbbf24}.score.info{color:#34d399}.muted{color:#64748b}.host-ip{font-style:normal;font-size:11px;font-weight:400;color:#64748b;margin-left:6px}.drawer-score{justify-content:space-between;margin-bottom:16px;padding:16px;border-radius:12px;background:linear-gradient(110deg,rgba(99,102,241,.17),rgba(34,211,238,.06))}.drawer-score span{color:#94a3b8}.drawer-score strong{display:block;font-size:34px}.drawer-score strong.critical{color:#f87171}.drawer-score strong.warning{color:#fbbf24}.drawer-score strong.info{color:#34d399}.drawer-score p{margin:6px 0 0;color:#94a3b8;font-size:12px}.drawer-section{margin-top:26px}.correlation-note{margin:7px 0;color:#64748b;font-size:12px}.correlation{margin-top:10px;padding:14px;border:1px solid rgba(99,102,241,.2);border-radius:10px;background:linear-gradient(115deg,rgba(99,102,241,.1),rgba(17,28,46,.55))}.correlation-head{display:flex;align-items:center;justify-content:space-between;gap:12px;color:#e5edf7}.correlation p{margin:8px 0;color:#cbd5e1;font-size:13px;line-height:1.65}.correlation small{color:#94a3b8;font-size:12px}.impact-list{display:flex;flex-wrap:wrap;gap:6px;margin:9px 0}.impact-list span{padding:4px 7px;border-radius:6px;background:rgba(34,211,238,.08);color:#cbd5e1;font-size:11px}.impact-list i{color:#fbbf24;font-style:normal}.evidence{display:flex;gap:10px;padding:13px 0;border-bottom:1px solid rgba(148,163,184,.12)}.evidence b,.forecast b{color:#e5edf7}.evidence p{margin:5px 0;color:#cbd5e1;font-size:13px}.evidence small,.forecast span{color:#94a3b8;font-size:12px}.forecast{display:block;padding:12px 0;border-bottom:1px solid rgba(148,163,184,.12)}.forecast span{display:block;margin-top:5px}@media(max-width:850px){.hero,.panel-head{align-items:flex-start;flex-direction:column}.summary-grid{grid-template-columns:repeat(2,1fr)}.readiness-grid{grid-template-columns:1fr}.hero-actions{flex-wrap:wrap}.risk-table{font-size:12px}}
</style>
